const validateMigrationStep = `-- name: ValidateMigrationStep :one
UPDATE fyniq.migration_step
   SET state = $1, checks_file_id = $2, report = $3::jsonb,
       report_sha256 = $4, errors = $5, warnings = $6,
       validated_at = $7
 WHERE id = $8 AND state = 'validating'
RETURNING organisation_id, id, run_id, step, state, workbook_file_id, checks_file_id, report, report_sha256, errors, warnings, started_by, started_at, validated_at
`

type ValidateMigrationStepParams struct {
	State        string
	ChecksFileID *uuid.UUID
	Report       []byte
	ReportSha256 *string
	Errors       *int32
	Warnings     *int32
	ValidatedAt  *time.Time
	ID           uuid.UUID
}

// A validating step's report; none when the step is no longer validating.
func (q *Queries) ValidateMigrationStep(ctx context.Context, arg ValidateMigrationStepParams) (FyniqMigrationStep, error) {
	row := q.db.QueryRow(ctx, validateMigrationStep,
		arg.State,
		arg.ChecksFileID,
		arg.Report,
		arg.ReportSha256,
		arg.Errors,
		arg.Warnings,
		arg.ValidatedAt,
		arg.ID,
	)
	var i FyniqMigrationStep
	err := row.Scan(
		&i.OrganisationID,
		&i.ID,
		&i.RunID,
		&i.Step,
		&i.State,
		&i.WorkbookFileID,
		&i.ChecksFileID,
		&i.Report,
		&i.ReportSha256,
		&i.Errors,
		&i.Warnings,
		&i.StartedBy,
		&i.StartedAt,
		&i.ValidatedAt,
	)
	return i, err
}
